const vacancy = { ...$json };
const apiKey = String($env.OPENROUTER_API_KEY || "").trim();

if (!apiKey) {
  throw new Error("OPENROUTER_API_KEY is not configured");
}

if (
  !vacancy.openrouter_request ||
  typeof vacancy.openrouter_request !== "object"
) {
  throw new Error(
    `Missing OpenRouter request for vacancy ${vacancy.vacancy_id || "unknown"}`
  );
}

const retryableStatuses = new Set([
  429,
  500,
  502,
  503,
  504,
]);

const maxAttempts = 2;
let response = null;
let lastStatus = 0;

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    response = await this.helpers.httpRequest({
      method: "POST",
      url: "https://openrouter.ai/api/v1/chat/completions",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: vacancy.openrouter_request,
      json: true,
      timeout: 120000,
    });

    break;
  } catch (error) {
    lastStatus = Number(
      error?.statusCode ||
      error?.response?.statusCode ||
      error?.response?.status ||
      0
    );

    const canRetry =
      attempt < maxAttempts &&
      retryableStatuses.has(lastStatus);

    if (!canRetry) {
      throw new Error(
        `OpenRouter request failed for vacancy ${
          vacancy.vacancy_id || "unknown"
        }; HTTP ${lastStatus || "unknown"}`
      );
    }

    const delayMs = lastStatus === 429 ? 5000 : 2000;

    await new Promise((resolve) => {
      setTimeout(resolve, delayMs);
    });
  }
}

if (!response || typeof response !== "object") {
  throw new Error(
    `Empty OpenRouter response for vacancy ${
      vacancy.vacancy_id || "unknown"
    }`
  );
}

vacancy.openrouter_response = response;

return {
  json: vacancy,
};

const vacancy = { ...$json };
const response = vacancy.openrouter_response;

if (!response || typeof response !== 'object') {
  throw new Error(
    `Missing OpenRouter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const choice = response.choices?.[0];

if (!choice) {
  throw new Error(
    `Missing OpenRouter choice for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const finishReason = String(choice.finish_reason || '');

if (finishReason === 'length') {
  throw new Error(
    `Truncated cover letter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

if (finishReason === 'content_filter') {
  throw new Error(
    `Cover letter response blocked for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const rawContent = choice.message?.content;

if (typeof rawContent !== 'string' || !rawContent.trim()) {
  throw new Error(
    `Empty cover letter response for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

const cleanedContent = rawContent
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;

try {
  result = JSON.parse(cleanedContent);
} catch {
  throw new Error(
    `Invalid cover letter JSON for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }`
  );
}

function normalizePublicText(value) {
  return String(value || '')
    .replace(/\u00a0/g, ' ')
    .replace(/[\u2013\u2014\u2212]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\u2022/g, '-')
    .replace(/\u2192/g, '->')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeList(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry) =>
      normalizePublicText(entry).slice(0, 240)
    )
    .filter(Boolean)
    .slice(0, 5);
}

const coverLetter = normalizePublicText(result.cover_letter);

if (coverLetter.length < 300) {
  throw new Error(
    `Cover letter is too short for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }: ${coverLetter.length} characters`
  );
}

if (coverLetter.length > 1800) {
  throw new Error(
    `Cover letter is too long for vacancy ${
      vacancy.vacancy_id || 'unknown'
    }: ${coverLetter.length} characters`
  );
}

const unsupportedClaimChecks = [
  {
    pattern:
      /(?:имею|есть|подтвержден|практическ|работал|использовал|настраивал|администрировал|владею|знаю|применял|опыт|стандартн\w*\s+инструмент).{0,80}(?:active directory|group policy|\bgpo\b)/i,
    label: 'claimed Active Directory or Group Policy experience',
  },
  {
    pattern:
      /(?:active directory|group policy|\bgpo\b).{0,80}(?:использовал|настраивал|администрировал|владею|знаю|применял|опыт|практик|моей практике)/i,
    label: 'claimed Active Directory or Group Policy experience',
  },
  {
    pattern: /\bbash\b/i,
    label: 'Bash',
  },
  {
    pattern: /\bansible\b/i,
    label: 'Ansible',
  },
  {
    pattern: /\bkubernetes\b|\bk8s\b/i,
    label: 'Kubernetes',
  },
  {
    pattern: /\bterraform\b/i,
    label: 'Terraform',
  },
  {
    pattern:
      /(?:имею|есть|подтвержден|практическ|работал|использовал|настраивал|администрировал|владею|знаю|применял|опыт).{0,80}\b(?:ospf|bgp|isis)\b/i,
    label: 'claimed experience with advanced routing protocols',
  },
  {
    pattern:
      /\b(?:ospf|bgp|isis)\b.{0,80}(?:использовал|настраивал|администрировал|владею|знаю|применял|опыт|практик)/i,
    label: 'claimed experience with advanced routing protocols',
  },
  {
    pattern: /\basterisk\b/i,
    label: 'Asterisk',
  },
  {
    pattern: /\bhelpdesk\b|\bservice desk\b|\bjira\b/i,
    label: 'ticket systems',
  },
  {
    pattern: /\bbitrix24\b|битрикс24|битрикс 24/i,
    label: 'Bitrix24',
  },
  {
    pattern: /getcourse/i,
    label: 'GetCourse',
  },
  {
    pattern: /наставнич|руковод\w*\s+команд|координац\w*\s+команд/i,
    label: 'team leadership or mentoring',
  },
  {
    pattern: /полностью соответств|в полной мере соответств|идеально подхож|уверен,\s*что\s+(?:мой опыт\s+)?подхож/i,
    label: 'unsupported fit claim',
  },
];

const detectedUnsupportedClaims = unsupportedClaimChecks
  .filter((check) => check.pattern.test(coverLetter))
  .map((check) => check.label);

const deterministicWarnings =
  detectedUnsupportedClaims.map(
    (claim) => `Potential unsupported claim: ${claim}`
  );

const factsUsed = normalizeList(result.facts_used);

// Не сохраняем общие инструкции, которые модель иногда
// возвращает в warnings. Сохраняем только результаты
// детерминированной проверки созданного письма.
const warnings = deterministicWarnings.slice(0, 5);
const requiresReview = warnings.length > 0;

let analysis = {};

if (
  vacancy.analysis_json &&
  typeof vacancy.analysis_json === 'object'
) {
  analysis = vacancy.analysis_json;
} else if (
  typeof vacancy.analysis_json === 'string' &&
  vacancy.analysis_json.trim()
) {
  try {
    analysis = JSON.parse(vacancy.analysis_json);
  } catch {
    analysis = {};
  }
}

analysis.cover_letter_generation = {
  model: String(
    response.model ||
      vacancy.openrouter_request?.model ||
      ''
  ),
  generated_at: $now.toUTC().toISO(),
  finish_reason: finishReason,
  facts_used: factsUsed,
  warnings,
  requires_review: requiresReview,
  usage: response.usage || {},
};

vacancy.cover_letter = coverLetter;
vacancy.status = requiresReview
  ? 'letter_review'
  : 'letter_ready';
vacancy.updated_at = $now.toUTC().toISO();
vacancy.analysis_json = JSON.stringify(analysis);
vacancy.last_error = '';

delete vacancy.openrouter_request;
delete vacancy.openrouter_response;
delete vacancy.letter_analysis;
delete vacancy.letter_recommended_resume;
delete vacancy.letter_score;
delete vacancy.letter_decision;
delete vacancy.letter_blocking_reasons;
delete vacancy.detected_salary_upper_bound;

return {
  json: vacancy,
};

return $input.all().map((item) => {
  const vacancy = item.json;

  let analysis = {};

  try {
    analysis =
      typeof vacancy.analysis_json === 'string'
        ? JSON.parse(vacancy.analysis_json)
        : vacancy.analysis_json || {};
  } catch {
    analysis = {};
  }

  const evaluation =
    analysis.evaluation &&
    typeof analysis.evaluation === 'object'
      ? analysis.evaluation
      : analysis;

  return {
    json: {
      vacancy_id: String(vacancy.vacancy_id || ''),
      url: String(vacancy.url || ''),
      title: String(vacancy.title || ''),
      company: String(vacancy.company || ''),
      salary: String(vacancy.salary || ''),
      location: String(vacancy.location || ''),
      work_format: String(vacancy.work_format || ''),
      score: Number(
        vacancy.score ||
          evaluation.score ||
          0
      ),
      decision: String(
        evaluation.decision ||
          (
            Number(vacancy.score || evaluation.score || 0) >= 75
              ? 'recommend'
              : Number(vacancy.score || evaluation.score || 0) >= 60
                ? 'review'
                : 'reject'
          )
      ),
      recommended_resume: String(
        vacancy.recommended_resume ||
          evaluation.recommended_resume ||
          ''
      ),
      status: String(vacancy.status || ''),
      cover_letter: String(vacancy.cover_letter || ''),
      facts_used:
        analysis.cover_letter_generation?.facts_used || [],
      warnings:
        analysis.cover_letter_generation?.warnings || [],
      model:
        analysis.cover_letter_generation?.model || '',
      generated_at:
        analysis.cover_letter_generation?.generated_at || '',
    },
  };
});
